import { getServerSideURL } from '@/utilities/getURL'

export const dynamic = 'force-dynamic'

/**
 * Sitemap index served at /sitemap.xml — this is the single URL to submit in
 * Search Console / Merchant Center. It was previously a stale static file
 * generated by next-sitemap at build time, which shipped `http://localhost:3000`
 * URLs whenever NEXT_PUBLIC_SERVER_URL was not set during the build.
 */
export async function GET() {
  const SITE_URL = getServerSideURL()
  const lastmod = new Date().toISOString()

  const sitemaps = [`${SITE_URL}/pages-sitemap.xml`, `${SITE_URL}/products-sitemap.xml`]

  const body = `<?xml version="1.0" encoding="UTF-8"?>
<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${sitemaps
  .map((loc) => `  <sitemap><loc>${loc}</loc><lastmod>${lastmod}</lastmod></sitemap>`)
  .join('\n')}
</sitemapindex>`

  return new Response(body, {
    headers: {
      'Content-Type': 'application/xml; charset=utf-8',
      'Cache-Control': 'public, max-age=0, s-maxage=3600, stale-while-revalidate=86400',
    },
  })
}
